def main() -> None:
    if sys.version_info < (3, 9):
        print(f"Python 3.9 or newer is needed. This is {sys.version.split()[0]}.")
        raise SystemExit(1)

    existing = (TARGET / "data" / "kaispot.db").exists()
    print()
    print("  KAISPOT Voucher Management v3.0")
    print("  " + "-" * 44)
    if existing:
        print("  Refreshing the code. Your data will not be touched.")
    print(f"  Writing into {TARGET}")
    print()

    written = 0
    for relative, blob in FILES.items():
        path = TARGET / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(blob))
        written += 1

    for folder in ("data", "data/uploads", "backups"):
        (TARGET / folder).mkdir(parents=True, exist_ok=True)

    for script in ("start.sh", "run.py"):
        path = TARGET / script
        if path.exists():
            try:
                path.chmod(0o755)
            except OSError:
                pass

    print(f"  {written} files written.")
    print()
    print("  Start it with:")
    print()
    if sys.platform.startswith("win"):
        print("      double-click start.bat")
    else:
        print("      ./start.sh")
    print()
    print("  First sign-in is  admin / admin  and you will be asked to")
    print("  change it straight away.")
    print()
    print("  Read README.txt for the walled-garden rule and everything else.")
    print()


if __name__ == "__main__":
    main()
